(()=>{
'use strict';
const KEY='aisports-ai-workbench-prototype-v1',app=document.getElementById('app'),dialog=document.getElementById('dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={events:[],promotions:[]};try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.events)&&Array.isArray(saved.promotions))state=saved}catch{}
for(const e of state.events){e.units=e.units||[];e.fields=e.fields||[]}
let page='home',selected=state.events[0]?.id||null,task='overview',mode='ai',phase='upload',filename='',channel='小红书',outputs={},goal='',audience='同城羽毛球爱好者',tone='亲切、清晰',toastTimer;
const tabs=[['overview','概览'],['projects','项目与费用'],['registrations','报名名单'],['fields','报名设置'],['checkin','赛事报到'],['matches','场次与录分'],['awards','获奖证明'],['publication','发布管理'],['notifications','取消通知']];
const seed={name:'秋日羽毛球交流赛',date:'2026-11-08',deadline:'2026-11-01',location:'演示体育馆',sport:'羽毛球',fee:'免费',review:'人工审核',status:'草稿',units:[],fields:[]};
let candidate={...seed,date:'',location:''};const current=()=>state.events.find(e=>e.id===selected);
const btn=(label,action,cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${label}</button>`;
function notify(text){document.getElementById('toast').textContent=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast').textContent='',3000)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{notify('浏览器不允许保存，数据仅保留在本页')}}
function go(next){page=next;render();window.scrollTo(0,0)}
function work(id,key='overview'){selected=id;task=key;go('workspace')}
function popup(title,html){document.getElementById('dialog-title').textContent=title;document.getElementById('dialog-content').innerHTML=html;dialog.showModal()}
function values(form){return Object.fromEntries(new FormData(form))}
function check(v){if(!v.name?.trim()||!v.date||!v.deadline||!v.location?.trim()||!v.sport?.trim()||!v.fee?.trim())return '请补全必填信息。';if(v.deadline>v.date)return '报名截止日期不能晚于比赛日期。';return ''}
function save(v,id){let e=state.events.find(x=>x.id===id);if(e)Object.assign(e,v);else{e={...v,id:'demo-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6),status:'草稿',review:v.review||'人工审核',units:[],fields:[]};state.events.unshift(e)}selected=e.id;persist();return e}
function art(){return `<svg class="hero-art" viewBox="0 0 500 150" aria-hidden="true"><path d="M0 125Q140 0 260 90T500 75" fill="none" stroke="#83dfe0" stroke-width="28" opacity=".45"/><path d="M0 135Q140 10 260 100T500 85" fill="none" stroke="#72cfd8"/><path d="M325 65h110m-96 0V47l10-9 10 9v18m25 0V30l9-9 9 9v35m-20-32h22" fill="none" stroke="#7abec7" opacity=".5"/><circle cx="200" cy="70" r="4" fill="#14bdc5"/><circle cx="335" cy="97" r="4" fill="#727dec"/><circle cx="416" cy="48" r="5" fill="#41aeb9"/><path d="m416 57-11 15 16 7m-16-7-13 1m29 6 11 13m-27-20-8 17-13 9m24-31 15 5 12-9" fill="none" stroke="#41aeb9" stroke-width="4" stroke-linecap="round"/></svg>`}
function eventTable(){return state.events.length?`<div class="table-wrap"><table><thead><tr><th>赛事名称</th><th>时间与地点</th><th>状态</th><th>操作</th></tr></thead><tbody>${state.events.map(e=>`<tr><td><strong>${esc(e.name)}</strong><div class="subline">示例赛事 · ${esc(e.sport)}</div></td><td>${esc(e.date)}<div class="subline">${esc(e.location)}</div></td><td><span class="badge amber">${esc(e.status)}</span></td><td><div class="row">${btn('编辑资料','edit','text',`data-id="${esc(e.id)}"`)}${btn('项目设置','open-projects','text',`data-id="${esc(e.id)}"`)}${btn('报名管理','open-registrations','text',`data-id="${esc(e.id)}"`)}${btn('预览','preview','text',`data-id="${esc(e.id)}"`)}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">还没有演示赛事。可以手动创建，或从示例规程开始。</div>'}
function manual(id){const e=state.events.find(x=>x.id===id)||{...seed,name:'',date:'',deadline:'',location:''};popup(id?'手动编辑赛事':'手动创建赛事',`<form id="manual-form" data-id="${esc(id||'')}"><div class="form-grid"><label class="field full"><span>赛事名称 *</span><input name="name" required maxlength="80" value="${esc(e.name)}"></label><label class="field"><span>比赛日期 *</span><input name="date" type="date" required value="${esc(e.date)}"></label><label class="field"><span>报名截止日期 *</span><input name="deadline" type="date" required value="${esc(e.deadline)}"></label><label class="field full"><span>比赛地点 *</span><input name="location" required maxlength="200" value="${esc(e.location)}"></label><label class="field"><span>运动项目说明 *</span><input name="sport" required value="${esc(e.sport)}"></label><label class="field"><span>公开收费说明 *</span><input name="fee" required value="${esc(e.fee)}"></label></div><p class="subline">说明与实际项目收费分别配置。本表单为交互切片，不自动发布。</p><p class="error" id="manual-error" role="alert"></p><div class="actions">${btn('取消','close')}<button class="btn primary" type="submit">保存草稿</button></div></form>`)}
function aiPage(){return `<div class="section-head"><div><h1>核对资料，完善赛事草稿</h1><p>原文有依据，缺项可补充，结果由你确认。</p></div>${btn('改用手动创建','manual','outline')}</div><div class="steps"><span class="${phase==='upload'?'active':''}">1 上传资料</span><span class="${phase==='review'?'active':''}">2 核对信息</span><span>3 保存草稿</span></div>${goal?`<div class="tip" style="margin-bottom:18px">当前目标：${esc(goal)}。识别仍使用示例规程。</div>`:''}${phase==='upload'?`<section class="panel"><h2>从一份规程开始</h2><p class="muted" style="margin:12px 0">可以选择文件查看上传入口。此独立原型不会读取、上传或解析你的文件；识别结果始终来自示例。</p><label class="field"><span>选择本地资料（不上传）</span><input id="file" type="file" accept=".docx,.pdf,.png,.jpg,.txt"></label><p id="file-note" class="subline">${esc(filename||'未选择文件')}</p><div class="actions">${btn('加载示例规程','sample','primary')}</div></section>`:phase==='running'?`<section class="panel"><div class="busy" role="status">正在演示资料识别，整理示例字段与冲突…</div><div class="actions">${btn('取消识别','cancel-ai')}</div></section>`:`<div class="grid"><section class="panel"><div class="title-row"><h3>规程原文</h3><span class="badge">示例资料</span></div><div class="source">秋日羽毛球交流赛\n比赛时间：<mark>2026年11月7日</mark>\n报名截止：2026年11月1日\n补充说明：比赛时间调整为<mark>11月8日</mark>\n比赛地点：待定\n运动项目：羽毛球\n收费说明：免费</div><p class="subline">选择文件：${esc(filename||'无')}。本原型不读取内容。</p></section><section class="panel"><div class="title-row"><h3>识别结果</h3><span class="badge amber">待人工确认</span></div><form id="ai-form"><div class="form-grid"><label class="field full"><span>赛事名称 *</span><input name="name" required value="${esc(candidate.name)}"></label><label class="field full"><span>比赛日期 · 原文有冲突 *</span><select name="date" required><option value="">请选择确认后的日期</option><option value="2026-11-07" ${candidate.date==='2026-11-07'?'selected':''}>2026-11-07 · 原规程</option><option value="2026-11-08" ${candidate.date==='2026-11-08'?'selected':''}>2026-11-08 · 补充说明</option></select></label><label class="field full"><span>比赛地点 · 待补充 *</span><input name="location" required placeholder="填写确认后的场地" value="${esc(candidate.location)}"></label><label class="field"><span>报名截止 *</span><input name="deadline" type="date" required value="${esc(candidate.deadline)}"></label><label class="field"><span>运动项目说明 *</span><input name="sport" required value="${esc(candidate.sport)}"></label><label class="field full"><span>公开收费说明 *</span><input name="fee" required value="${esc(candidate.fee)}"></label></div><div class="notice">尚未创建赛事<small>人工确认后保存草稿，继续手动配置项目、名额和收费。</small></div><p class="error" id="ai-error" role="alert"></p><div class="actions">${btn('保留修改，稍后继续','keep-ai')}<button type="submit" class="btn primary">确认并保存草稿</button></div></form></section></div>`}`}
function workspace(){const e=current();if(!e)return '<section class="panel empty">请先选择演示赛事。</section>';return `<div class="section-head"><div><p class="subline">演示组织 / 赛事工作区</p><h1>${esc(e.name)}</h1><p>${esc(e.location)} · ${esc(e.date)}</p></div><div class="row">${btn('预览参赛者页面','preview','',`data-id="${esc(e.id)}"`)}${btn('返回赛事列表','events','text')}</div></div><div class="context"><span>发布状态：<strong>${esc(e.status)}</strong></span><span>举办阶段：示例未开赛</span><span>审核方式：${esc(e.review)}</span><span class="badge blue">本地原型</span></div><div class="task-tabs" aria-label="赛事任务">${tabs.map(([key,label])=>`<button data-task="${key}" class="${task===key?'active':''}">${label}</button>`).join('')}</div>${taskBody(e)}`}
function taskBody(e){if(task==='overview')return `<div class="grid"><section class="panel"><div class="title-row"><h3>基础信息</h3>${btn('手动编辑','edit','outline',`data-id="${esc(e.id)}"`)}</div><div class="kv"><div><small>报名截止</small><strong>${esc(e.deadline)}</strong></div><div><small>比赛日期</small><strong>${esc(e.date)}</strong></div><div><small>运动项目说明</small><strong>${esc(e.sport)}</strong></div><div><small>公开收费说明</small><strong>${esc(e.fee)}</strong></div></div></section><section class="panel"><h3>下一步</h3><div class="notice">${e.units.length?'核对配置与发布条件':'请先配置项目与实际收费'}<small>填写赛事说明不会自动创建报名项目。</small></div><div class="row">${btn('项目与费用','projects','primary')}${btn('发布管理','publication','outline')}${btn('生成推广','marketing','text')}</div></section></div>`;
if(task==='projects')return `<section class="panel"><div class="title-row"><h3>项目与费用</h3>${btn('新增竞赛项目','add-unit','primary',e.status!=='草稿'?'disabled':'')}</div>${e.units.length?`<div class="table-wrap"><table><thead><tr><th>项目</th><th>整单容量</th><th>收费</th><th>操作</th></tr></thead><tbody>${e.units.map((u,i)=>`<tr><td>${esc(u.name)} · ${esc(u.type)}</td><td>${u.capacity} ${u.type==='双打'?'对':'人'}</td><td>${u.amount===0?'免费':'¥'+u.amount+' / 整单'}</td><td>${btn('编辑','edit-unit','text',`data-index="${i}" ${e.status!=='草稿'?'disabled':''}`)}${btn('移除','remove-unit','text',`data-index="${i}" ${e.status!=='草稿'?'disabled':''}`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">尚未配置竞赛项目</div>'}<p class="subline">无正式报名历史的交互示例。真实收费还需收款方式与退改政策，不能用本页替代。</p></section>`;
if(task==='registrations')return `<section class="panel"><div class="title-row"><h3>报名名单</h3><span class="badge">只读虚构示例</span></div><p class="muted">以下名单仅展示布局，不是刚创建赛事的实际报名。</p><div class="table-wrap"><table><thead><tr><th>报名</th><th>资格</th><th>付款声明</th><th>有效实收</th><th>操作</th></tr></thead><tbody><tr><td>示例单打报名</td><td>待审核</td><td>已声明</td><td>¥0 / 应付 ¥100</td><td>${btn('查看详情','entry','outline')}</td></tr><tr><td>示例免费报名</td><td>已通过</td><td>不需要</td><td>免费</td><td>${btn('查看详情','free-entry','text')}</td></tr></tbody></table></div><p class="subline">声明不等于到账；收费实际足额才可通过。此版不登记款项或提交审核。</p></section>`;
if(task==='fields')return `<section class="panel"><div class="title-row"><h3>报名设置</h3>${btn('添加示例采集字段','add-field','outline',e.status!=='草稿'?'disabled':'')}</div><label class="field"><span>审核方式（未提交前的演示配置）</span><select id="review" ${e.status!=='草稿'?'disabled':''}><option ${e.review==='人工审核'?'selected':''}>人工审核</option><option ${e.review==='无需人工审核'?'selected':''}>无需人工审核</option></select></label><div class="notice">首次正式提交后锁定配置<small>成员本人填写确认，队长不替成员确认敏感信息。</small></div><div class="mini-list">${e.fields.map(f=>`<article>${esc(f)} <span class="badge">文本 · 选填</span></article>`).join('')||'<p class="muted">尚未选择扩展字段。</p>'}</div></section>`;
if(task==='publication')return `<section class="panel"><h3>发布管理</h3><div class="kv"><div><small>基础信息</small><strong>已填写</strong></div><div><small>项目与费用</small><strong>${e.units.length?'已配置演示版本':'待配置'}</strong></div><div><small>当前状态</small><strong>${esc(e.status)}</strong></div></div><div class="notice">模拟发布只更改本地标记<small>不产生真实公开赛事、报名链接或支付能力。收费项目此版仅预览配置。</small></div><div class="row">${btn('预览','preview','outline',`data-id="${esc(e.id)}"`)}${btn(e.status==='草稿'?'模拟发布':'已模拟发布','publish','primary',e.status!=='草稿'?'disabled':'')}</div></section>`;
const info={checkin:['赛事报到','按竞赛项目核对有效资格及付款条件。本版不产生报到记录。'],matches:['场次与录分','选择项目和场次，比分与胜负分别核对。本版不录入或确认真实成绩。'],awards:['获奖证明','有依据的结果与授权访问继续保留。私人证明不自动公开，不等于官方等级。'],notifications:['取消通知','站内信、短信、送达和已读分别维护。本版不取消赛事或发送通知。']}[task];return `<section class="panel"><h3>${info[0]}</h3><div class="readonly">${info[1]}</div><div class="empty">任务入口与业务边界预览</div>${btn('查看示例报名详情','entry','outline')}</section>`}
function unitForm(index){const e=current(),u=e.units[index]||{name:'',type:'单打',capacity:32,amount:0};popup(index===undefined?'新增竞赛项目':'编辑竞赛项目',`<form id="unit-form" data-index="${index??''}"><div class="form-grid"><label class="field full"><span>项目名称 *</span><input name="name" required value="${esc(u.name)}"></label><label class="field"><span>类型</span><select name="type"><option ${u.type==='单打'?'selected':''}>单打</option><option ${u.type==='双打'?'selected':''}>双打</option></select></label><label class="field"><span>整单容量 *</span><input name="capacity" required type="number" min="1" max="9999" step="1" value="${u.capacity}"></label><label class="field full"><span>每整单金额（元，0 为免费）</span><input name="amount" required type="number" min="0" step="0.01" value="${u.amount}"></label></div><p class="error" id="unit-error" role="alert"></p><div class="actions"><button class="btn primary" type="submit">保存项目</button></div></form>`)}
function entry(free){popup('报名详情 · 虚构只读示例',`<div class="context"><strong>${free?'示例免费报名':'示例单打报名'}</strong><span class="badge amber">${free?'已通过':'待审核'}</span></div><h3 style="margin-top:20px">冻结名单</h3><div class="readonly">示例参赛者 · 单打 · 本人资料已确认</div><h3>资格与资金分别核对</h3><div class="kv"><div><small>资格</small><strong>${free?'已通过':'待审核'}</strong></div><div><small>付款声明</small><strong>${free?'不需要':'已声明 · 不等于到账'}</strong></div><div><small>本次应付</small><strong>${free?'免费':'¥100'}</strong></div><div><small>有效实收</small><strong>¥0</strong></div></div><div class="notice">${free?'免费不产生付款义务':'尚未足额到账，不能通过'}<small>资金办理集中报名详情，资金权限与审核权限分开。</small></div><h3>收费记录与退款</h3><p class="muted">无实际收款记录，本页不登记款项。</p><div class="actions">${btn('返回报名列表','close','outline')}</div>`)}
function promotion(){const options=state.events.length?state.events:[{...seed,id:'sample'}],e=current()||options[0];return `<div class="section-head"><div><h1>让赛事，被更多人看见</h1><p>编辑核对后由你发布，AI 与手动操作相互配合。</p></div>${btn('回到工作台','home','text')}</div><div class="context"><strong>${esc(e.name)}</strong><span class="badge amber">${esc(e.status)}</span><span>原型不提供真实报名链接</span></div><div class="grid" style="margin-top:22px"><section class="panel"><h3>生成设置</h3><label class="field" style="margin-top:18px"><span>依据赛事</span><select id="promotion-event">${options.map(x=>`<option value="${esc(x.id)}" ${x.id===e.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="field" style="margin-top:16px"><span>目标受众</span><input id="audience" value="${esc(audience)}"></label><label class="field" style="margin-top:16px"><span>内容风格</span><select id="tone">${['亲切、清晰','简洁、专业','活力、轻松'].map(v=>`<option ${v===tone?'selected':''}>${v}</option>`).join('')}</select></label><div class="tip">本地模板生成示例，无真实模型调用。</div><div class="actions">${btn('✦ 生成推广内容','generate','ai')}</div></section><section class="panel"><h3>推广内容</h3><div class="channel-tabs">${['公众号','小红书','短视频脚本'].map(c=>btn(c,'channel','small '+(channel===c?'active':''),`data-channel="${c}"`)).join('')}</div>${outputs[channel]?`<textarea id="promotion-copy" class="copy" aria-label="推广文案">${esc(outputs[channel])}</textarea><p class="subline">依据演示赛事生成，发布前请核对事实。</p><div class="actions">${btn('复制内容','copy')}${btn('重新生成','generate')}${btn('保存文案','save-copy','primary')}</div>`:'<div class="empty">选择赛事与风格，生成后可直接编辑。</div>'}<p class="storage-note">已保存 ${state.promotions.length} 条本地文案</p>${state.promotions.length?btn('查看已保存文案','saved-copy','text'):''}</section></div>`}
function renderPage(){document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page||(page==='workspace'&&b.dataset.page==='events')));if(page==='home')app.innerHTML=home();else if(page==='ai')app.innerHTML=aiPage();else if(page==='workspace')app.innerHTML=workspace();else if(page==='marketing')app.innerHTML=promotion();else if(page==='events')app.innerHTML=`<div class="section-head"><div><h1>赛事管理</h1><p>手动与 AI 创建的草稿进入同一赛事工作区。</p></div><div class="row">${btn('✦ AI办赛','ai','ai ai-primary')}${btn('手动创建','manual','outline manual-primary')}</div></div><section class="panel">${eventTable()}</section>`;else if(page==='organization')app.innerHTML=`<h1 style="margin-bottom:24px">组织设置</h1><section class="panel"><h3>演示组织</h3><div class="readonly">当前是原型身份，不连接真实账号或组织。</div><p class="muted">组织字段目录、组织授权和申请进度沿原业务保留。赛事管理与资金办理权限在正式系统分别校验。</p></section>`;else app.innerHTML=`<div class="section-head"><div><h1>${page==='registrations'?'报名管理':'现场执行'}</h1><p>先选择赛事，保留组织与赛事上下文。</p></div></div><section class="panel">${state.events.length?state.events.map(e=>`<div class="title-row"><strong>${esc(e.name)}</strong>${btn('进入赛事工作区','pick-event','outline',`data-id="${esc(e.id)}"`)}</div>`).join(''):'<div class="empty">尚无演示赛事，请先创建。</div>'}</section>`}
// 面包屑按业务归属展示，只在下级页面出现；不引入已打开页面标签栏。
function render(){renderPage();renderBreadcrumb()}
function renderBreadcrumb(){const items=[];if(page==='workspace'){items.push(btn('赛事管理','events','text'));const e=current();if(task!=='overview')items.push(btn(esc(e?.name||'赛事工作区'),'continue','text',`data-id="${esc(e?.id)}"`));else items.push(`<span aria-current="page">${esc(e?.name||'赛事工作区')}</span>`);if(task!=='overview')items.push(`<span aria-current="page">${esc(tabs.find(x=>x[0]===task)?.[1])}</span>`)}else if(page==='ai'){items.push(btn('赛事管理','events','text'),'<span aria-current="page">AI办赛</span>')}else if(page==='marketing'){items.push(btn('运营概览','home','text'),'<span aria-current="page">AI推广</span>')}if(items.length){const nav=document.createElement('nav');nav.className='business-breadcrumb';nav.setAttribute('aria-label','当前位置');nav.innerHTML=items.join('<span class="crumb-divider" aria-hidden="true">/</span>');app.prepend(nav)}}
function keepCopy(){const el=document.getElementById('promotion-copy');if(el)outputs[channel]=el.value}
document.addEventListener('click',event=>{const nav=event.target.closest('[data-page]');if(nav){go(nav.dataset.page);return}const tab=event.target.closest('[data-task]');if(tab){task=tab.dataset.task;render();return}const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,id=b.dataset.id,e=current();
if(action==='close'){dialog.close();return}if(['home','events','marketing'].includes(action)){go(action);return}if(action==='manual'){manual();return}if(action==='edit'){const item=state.events.find(x=>x.id===id);if(item?.status!=='草稿'){notify('已模拟发布赛事保持只读，真实变更沿原业务规则办理');return}manual(id);return}if(action==='mode-ai'||action==='mode-manual'){const input=document.getElementById('goal');if(input)goal=input.value;mode=action==='mode-ai'?'ai':'manual';render();return}if(action==='ai'){const input=document.getElementById('goal');if(input)goal=input.value;go('ai');return}if(action==='sample'){phase='running';go('ai');setTimeout(()=>{if(phase==='running'){phase='review';render()}},600);return}if(action==='cancel-ai'){phase='upload';go('home');return}if(action==='keep-ai'){candidate={...candidate,...values(document.getElementById('ai-form'))};go('home');notify('修改保留在本页，可返回识别入口继续');return}if(action==='confirm-ai'){b.disabled=true;const item=save(candidate);phase='upload';candidate={...seed,date:'',location:''};dialog.close();work(item.id);notify('已确认保存演示草稿，继续配置项目');return}if(action==='continue'||action==='open-projects'||action==='open-registrations'){work(id,action==='open-projects'?'projects':action==='open-registrations'?'registrations':'overview');return}if(action==='pick-event'){work(id,page==='registrations'?'registrations':'checkin');return}if(action==='projects'||action==='publication'){task=action;render();return}if(action==='preview'){const item=state.events.find(x=>x.id===id)||seed;popup('参赛者页面预览 · 示例',`<div class="panel"><span class="badge amber">${esc(item.status)}</span><h2 style="margin:15px 0">${esc(item.name)}</h2><p>${esc(item.date)} · ${esc(item.location)}</p><p>${esc(item.sport)} · ${esc(item.fee)}</p><div class="notice">没有真实报名入口<small>不占名额、不产生付款、不对外发布。</small></div></div>`);return}if(action==='add-unit'||action==='edit-unit'){if(e.status!=='草稿')return;unitForm(action==='edit-unit'?Number(b.dataset.index):undefined);return}if(action==='remove-unit'){if(e.status!=='草稿')return;e.units.splice(Number(b.dataset.index),1);persist();render();return}if(action==='add-field'){if(!e.fields.includes('紧急联系称呼'))e.fields.push('紧急联系称呼');persist();render();return}if(action==='entry'||action==='free-entry'){entry(action==='free-entry');return}if(action==='publish'){if(!e.units.length){notify('请先配置至少一个项目及其费用');return}if(e.units.some(u=>u.amount>0)){notify('收费项目此版仅预览配置；收款主体和退改政策未配置，不模拟发布');return}popup('确认模拟发布',`<p>仅在本浏览器标记“${esc(e.name)}”，不会创建公开赛事或真实报名链接。</p><div class="actions">${btn('取消','close')}${btn('确认模拟发布','confirm-publish','primary')}</div>`);return}if(action==='confirm-publish'){e.status='模拟已发布';persist();dialog.close();render();notify('已模拟发布，仅当前浏览器可见');return}if(action==='channel'){keepCopy();channel=b.dataset.channel;render();return}if(action==='generate'){audience=document.getElementById('audience').value.trim()||'运动爱好者';tone=document.getElementById('tone').value;const source=e||seed;outputs={公众号:`${source.name}\n\n面向${audience}的一场交流活动。\n比赛日期：${source.date}\n地点：${source.location}\n公开收费说明：${source.fee}\n\n语气：${tone}。请以最终发布规程为准。\n报名链接：未提供（原型演示）`,小红书:`这个秋天，一起上场！\n\n${source.name}，欢迎${audience}。\n时间：${source.date}\n地点：${source.location}\n${source.fee}\n\n#羽毛球 #同城运动\n\n${tone} · 示例内容，发布前核对。无真实报名链接。`,短视频脚本:`[开场] 羽毛球场与运动准备画面\n[介绍] ${source.name}\n[信息] ${source.date}，${source.location}\n[受众] ${audience}\n[结尾] 关注最终发布信息，报名链接待配置。\n\n语气：${tone}。本段为原型模板示例。`};render();notify('已生成本地模板示例，可以编辑');return}if(action==='save-copy'){keepCopy();state.promotions.push({channel,text:outputs[channel],eventId:selected,at:new Date().toISOString()});persist();render();notify('文案已保存到本浏览器');return}if(action==='saved-copy'){popup('已保存文案',`<div class="mini-list">${state.promotions.map(p=>`<article><strong>${esc(p.channel)}</strong><p style="white-space:pre-wrap">${esc(p.text)}</p></article>`).join('')}</div>`);return}if(action==='copy'){const text=document.getElementById('promotion-copy').value;if(navigator.clipboard)navigator.clipboard.writeText(text).then(()=>notify('已复制')).catch(()=>notify('请选中文案手动复制'));else notify('请选中文案手动复制');return}if(action==='reset'){popup('重置演示数据',`<p>仅清除本原型的草稿和文案，不影响真实业务及其他页面。</p><div class="actions">${btn('取消','close')}${btn('确认重置','confirm-reset','outline')}</div>`);return}if(action==='confirm-reset'){state={events:[],promotions:[]};selected=null;outputs={};candidate={...seed,date:'',location:''};phase='upload';persist();dialog.close();go('home');notify('已重置本原型数据');return}});
document.addEventListener('submit',event=>{const form=event.target;if(!['manual-form','ai-form','unit-form'].includes(form.id))return;event.preventDefault();const v=values(form);if(form.id==='unit-form'){const e=current(),i=form.dataset.index,name=v.name.trim(),capacity=Number(v.capacity),amount=Number(v.amount);if(!name||!Number.isInteger(capacity)||capacity<1||!Number.isFinite(amount)||amount<0){document.getElementById('unit-error').textContent='请核对名称、正整数容量与非负金额。';return}if(e.units.some((u,n)=>u.name===name&&String(n)!==i)){document.getElementById('unit-error').textContent='当前赛事项目名称不能重复。';return}const unit={name,type:v.type,capacity,amount};if(i==='')e.units.push(unit);else e.units[Number(i)]=unit;persist();dialog.close();render();notify('演示项目已保存');return}const error=check(v);document.getElementById(form.id==='manual-form'?'manual-error':'ai-error').textContent=error;if(error)return;if(form.id==='ai-form'){candidate={...candidate,...v};popup('确认保存赛事草稿',`<p>将人工核对后的字段保存到本浏览器，不自动发布。</p><div class="kv"><div><small>赛事</small><strong>${esc(v.name)}</strong></div><div><small>日期</small><strong>${esc(v.date)}</strong></div><div><small>地点</small><strong>${esc(v.location)}</strong></div><div><small>状态</small><strong>草稿</strong></div></div><div class="actions">${btn('返回修改','close')}${btn('确认保存','confirm-ai','primary')}</div>`);return}const item=save(v,form.dataset.id);dialog.close();work(item.id);notify('草稿已保存到本浏览器')});
document.addEventListener('change',event=>{if(event.target.id==='file'){filename=event.target.files[0]?.name||'';document.getElementById('file-note').textContent=filename?'已选择：'+filename+'。不上传、不解析，请加载示例。':'未选择文件'}if(event.target.id==='review'){current().review=event.target.value;persist();notify('已保存演示审核方式')}if(event.target.id==='promotion-event'){selected=event.target.value;outputs={};render()}});
// 独立原型的运营快照与聊天组件；示例统计不混入真实或本地草稿统计。
function home(){return `<section class="hero ops-hero"><div><span class="eyebrow">EVENT OPERATIONS / 赛事运营</span><h1>掌握进展，从容办赛</h1><p>演示组织 · 2026年10月8日 · 所有运营统计为示例</p></div><div class="signal"><i></i> 运营快照 <small>DEMO</small></div></section><section class="metrics">${[['运营中赛事','03','2 场报名中 · 1 场举办中','01'],['正式提交报名','128','按整单统计 · 今日新增 12','02'],['待人工审核','18','其中 6 单收费未足额到账','03'],['今日报到','42 / 64','有效资格名单 · 已报到 66%','04']].map(([l,n,s,k])=>`<article class="metric"><span>${l}</span><b>${n}</b><small>${s}</small><em>${k}</em></article>`).join('')}</section><div class="ops-grid"><section class="panel ops-events"><div class="title-row"><div><span class="eyebrow">LIVE PORTFOLIO</span><h3>正在运营的赛事</h3></div><span class="badge blue">示例快照</span></div><article class="live-event"><div class="live-icon">◈</div><div><span class="badge">举办中</span><h2>城市羽毛球邀请赛</h2><p>今天 09:00–18:00 · 体育中心 A 馆</p><div class="event-progress"><span>报到 42 / 64</span><span>已完成场次 12 / 24</span></div><div class="progress-track"><i style="width:66%"></i></div></div><button class="btn outline" data-ops-detail="live">查看现场</button></article><article class="live-event"><div class="live-icon violet">↗</div><div><span class="badge blue">报名中</span><h2>秋季羽毛球公开赛</h2><p>10月18日 · 演示体育馆</p><div class="event-progress"><span>整单占用 64 / 80</span><span>待审 12 单</span></div><div class="progress-track"><i style="width:80%"></i></div></div><button class="btn outline" data-ops-detail="registration">查看报名</button></article><article class="live-event"><div class="live-icon">⌁</div><div><span class="badge blue">报名中</span><h2>周末双打交流赛</h2><p>10月24日 · 城北运动馆</p><div class="event-progress"><span>整单占用 32 / 48 对</span><span>待审 6 单</span></div><div class="progress-track"><i style="width:67%"></i></div></div><button class="btn outline" data-ops-detail="registration">查看报名</button></article></section><section class="panel priorities"><div class="title-row"><div><span class="eyebrow">ACTION CENTER</span><h3>需要你关注</h3></div><span class="badge amber">3 类待办</span></div><button data-ops-detail="registration"><i class="priority amber">18</i><span><b>报名资格待审核</b><small>先核对名单、成员确认与实收</small></span><span>↗</span></button><button data-ops-detail="funds"><i class="priority">6</i><span><b>收费报名未足额到账</b><small>付款声明与实际收款分别核对</small></span><span>↗</span></button><button data-ops-detail="live"><i class="priority violet">22</i><span><b>今日有效参赛者未报到</b><small>按项目确认名单，再办理报到</small></span><span>↗</span></button><div class="ai-insight"><span>✦ AI 观察 · 示例</span><p>公开赛名额占用达到 80%。建议先处理待审名单，再决定是否增加容量。</p><button data-chat-command="分析当前运营">一起分析 →</button></div></section></div><div class="ops-bottom"><section class="panel trend-panel"><div class="title-row"><h3>近 7 日正式提交趋势</h3><span class="subline">示例 · 整单</span></div><svg viewBox="0 0 600 130" role="img" aria-label="示例趋势：7日新增整单数为8、14、11、20、18、24、12"><defs><linearGradient id="trendFill" x2="0" y2="1"><stop stop-color="#26c8d8" stop-opacity=".35"/><stop offset="1" stop-color="#26c8d8" stop-opacity="0"/></linearGradient></defs><path d="M20 110H580M20 70H580M20 30H580" stroke="#e3edf4"/><path d="M20 100L110 77L200 90L290 54L380 62L470 38L580 84V130H20Z" fill="url(#trendFill)"/><path d="M20 100L110 77L200 90L290 54L380 62L470 38L580 84" fill="none" stroke="#20afbf" stroke-width="3"/></svg><div class="trend-labels"><span>10/02</span><span>10/03</span><span>10/04</span><span>10/05</span><span>10/06</span><span>10/07</span><span>10/08</span></div></section><section class="panel quick-start"><span class="eyebrow">YOUR NEXT EVENT</span><h3>✦ AI办赛，让筹备更轻松</h3><p>上传规程，AI整理赛事信息；核对后保存草稿。</p><div class="row">${btn('✦ AI办赛','ai','ai ai-primary')}${btn('手动创建','manual','outline manual-primary')}</div>${btn('生成推广文案','marketing','text')}</section></div><section class="panel recent"><div class="title-row"><h3>我的本地赛事草稿</h3>${btn('全部赛事 →','events','text')}</div>${eventTable()}</section><p class="storage-note">运营快照为固定虚构示例，与下方本地草稿分别统计。全局 AI 助手可读取页面上下文。</p>`}
const chatPanel=document.getElementById('chat-panel'),chatMessages=document.getElementById('chat-messages');
let chatOperation=null,chatCounter=0;
function contextSnapshot(){return {route:location.pathname,page,task:page==='workspace'?task:null,eventId:page==='workspace'||page==='marketing'?selected:null}}
function contextLabel(){const names={home:'赛事运营总览',events:'赛事管理',registrations:'报名管理',onsite:'现场执行',organization:'组织设置',ai:'资料识别',marketing:'推广文案',workspace:'赛事工作区'};return `${names[page]}${page==='workspace'?' / '+tabs.find(x=>x[0]===task)?.[1]:''}${contextSnapshot().eventId?' / '+(current()?.name||'未选择'):''}`}
function refreshChatContext(){document.getElementById('chat-context').textContent='当前上下文：'+contextLabel();document.getElementById('chat-context').title=location.pathname}
function chatMessage(content,user=false){const el=document.createElement('article');el.className='chat-message '+(user?'user':'assistant');el.innerHTML=content;chatMessages.append(el);el.scrollIntoView({block:'nearest'});return el}
function openChat(){chatPanel.hidden=false;document.getElementById('chat-launcher').setAttribute('aria-expanded','true');refreshChatContext();if(!chatMessages.children.length)chatMessage('<b>你好，我是你的赛事运营助手。</b><p>可以一起查看运营情况，也可以在这里创建赛事、修改草稿设置。你正在看的页面会保持原位。</p><small>本轮为本地模板交互演示，不调用真实模型。</small>');document.getElementById('chat-input').focus()}
function componentForm(edit){const e=current();if(edit&&(!contextSnapshot().eventId||!e)){chatMessage('请先通过手动入口选择一场赛事，再让我修改当前设置。我不会替你切换页面。');return}if(edit&&e.status!=='草稿'){chatMessage('当前赛事已模拟发布，本版不修改已发布赛事的业务配置。');return}chatOperation={id:edit?e.id:null,context:JSON.stringify(contextSnapshot()),token:++chatCounter};chatPanel.querySelectorAll('.chat-component').forEach(x=>{x.querySelectorAll('button,input,select').forEach(c=>c.disabled=true)});const v=edit?e:{...seed,name:'',date:'',deadline:'',location:''};chatMessage(`<p>${edit?'已读取当前赛事。修改后直接保存，当前页面保持原位。':'填写这张赛事卡片，即可在聊天内保存草稿。'}</p><form class="chat-component" data-chat-token="${chatOperation.token}"><h3>${edit?'修改赛事设置':'新建赛事草稿'}</h3>${[['name','赛事名称','text'],['date','比赛日期','date'],['deadline','报名截止','date'],['location','比赛地点','text'],['sport','运动项目说明','text'],['fee','公开收费说明','text']].map(([k,label,type])=>`<label class="field"><span>${label} *</span><input name="${k}" type="${type}" required value="${esc(v[k])}"></label>`).join('')}<label class="field"><span>审核方式</span><select name="review"><option ${v.review==='人工审核'?'selected':''}>人工审核</option><option ${v.review==='无需人工审核'?'selected':''}>无需人工审核</option></select></label><p class="chat-error error" role="alert"></p><button class="btn primary" type="submit">${edit?'保存设置':'保存赛事草稿'}</button><small>只保存本浏览器原型数据，不自动发布。</small></form>`)}
function reply(text){openChat();chatMessage(esc(text),true);if(/AI办赛|资料/.test(text)){componentForm(false);const form=chatMessages.lastElementChild.querySelector('.chat-component');if(form){const source=document.createElement('div');source.className='chat-ai-source';source.innerHTML='<b>✦ 从规程开始办赛</b><p>选择文件查看入口，或加载示例资料，再核对下方字段。此原型不读取、上传文件。</p><input type="file" aria-label="选择赛事规程" accept=".docx,.pdf,.png,.jpg,.txt"><button type="button" class="btn ai" data-chat-sample>加载示例规程</button><p class="chat-source-note"></p>';form.prepend(source)}return}if(/创建|新建/.test(text)){componentForm(false);return}if(/修改|设置/.test(text)){componentForm(true);return}if(/趋势|图表|数据组件/.test(text)){const frame=chatMessage('<p>为你展开近 7 日报名组件。整单口径，以下是示例数据。</p><iframe class="sandbox-chart" sandbox="" title="报名趋势沙盒组件"></iframe>');frame.querySelector('iframe').srcdoc=`<!doctype html><html lang="zh-CN"><meta charset="utf-8"><style>body{font:14px Segoe UI,sans-serif;color:#234558;padding:12px;background:#f2fafc}h3{margin:0}main{display:flex;height:130px;gap:12px;align-items:end;margin:18px 0}i{flex:1;background:linear-gradient(#54ddcf,#4776e7);border-radius:5px 5px 0 0;position:relative}b{position:absolute;top:-20px;width:100%;text-align:center;font-size:12px}p{font-size:12px}</style><h3>正式提交报名 / 整单</h3><main>${[8,14,11,20,18,24,12].map(n=>`<i style="height:${n*4}px"><b>${n}</b></i>`).join('')}</main><p>10月2日—8日 · 固定示例快照</p></html>`;return}const c=contextLabel();chatMessage(`<b>当前正在讨论：${esc(c)}</b><p>在演示运营快照中，18 单等待审核，其中 6 单收费尚未足额到账；今天还有 22 位有效参赛者待报到。</p><div class="chat-analysis"><span>01 / 报名审核</span><p>先确认成员与资格材料；收费足额后才可通过。</p><span>02 / 名额规划</span><p>公开赛整单占用率 80%，增容前确认场地与执行能力。</p><span>03 / 现场执行</span><p>核对有效名单、报到与场次安排。</p></div><small>以上为固定示例建议；本原型不会自动审核、记账或发送通知。可试“AI办赛”“修改当前赛事设置”“展示报名趋势”。</small>`)}
document.getElementById('chat-launcher').addEventListener('click',openChat);
document.getElementById('chat-close').addEventListener('click',()=>{chatPanel.hidden=true;document.getElementById('chat-launcher').setAttribute('aria-expanded','false');document.getElementById('chat-launcher').focus()});
document.getElementById('chat-expand').addEventListener('click',()=>{chatPanel.classList.toggle('expanded');document.getElementById('chat-expand').setAttribute('aria-label',chatPanel.classList.contains('expanded')?'缩小聊天窗口':'放大聊天窗口')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!chatPanel.hidden&&!dialog.open)document.getElementById('chat-close').click()});
document.addEventListener('click',e=>{const command=e.target.closest('[data-chat-command]');if(command)reply(command.dataset.chatCommand);const detail=e.target.closest('[data-ops-detail]');if(detail)popup('运营快照 · 只读示例',`<p>此卡片展示固定运营样例，不对应本地草稿或真实报名。</p><div class="notice">${detail.dataset.opsDetail==='live'?'现场：有效名单 64 人，已报到 42 人，完成 12 / 24 场。':'报名：待人工审核 18 单，其中 6 单收费未足额到账。'}</div><p>正式业务继续在赛事工作区办理，保持资格与资金状态分开。</p>`)});
document.addEventListener('submit',e=>{if(e.target.id==='chat-input-form'){e.preventDefault();const input=document.getElementById('chat-input'),text=input.value.trim();if(text){input.value='';reply(text)}return}const form=e.target.closest('.chat-component');if(!form)return;e.preventDefault();const error=form.querySelector('.chat-error');if(!chatOperation||String(chatOperation.token)!==form.dataset.chatToken){error.textContent='此组件已过期，请重新生成。';return}if(chatOperation.context!==JSON.stringify(contextSnapshot())){error.textContent='页面上下文已改变，请在当前页面重新提出修改。';return}const v=values(form),validation=check(v);if(validation){error.textContent=validation;return}const target=state.events.find(x=>x.id===chatOperation.id);if(chatOperation.id&&(!target||target.status!=='草稿')){error.textContent='赛事状态已改变，不能保存。';return}const priorSelected=selected,item=save(v,chatOperation.id);selected=priorSelected;form.querySelectorAll('input,select,button').forEach(x=>x.disabled=true);chatOperation=null;render();chatMessage(`<b>✓ 已保存${target?'设置':'赛事草稿'}</b><p>${esc(item.name)} · ${esc(item.date)} · ${esc(item.location)}</p><small>当前页面保持原位，手动入口和聊天读取同一份原型数据。</small>`);notify('聊天内保存成功，当前页面已同步')});
document.addEventListener('click',e=>{const button=e.target.closest('[data-chat-sample]');if(!button||button.disabled)return;const form=button.closest('.chat-component');for(const [key,value] of Object.entries({name:seed.name,deadline:seed.deadline,sport:seed.sport,fee:seed.fee,date:'',location:''}))form.querySelector(`[name="${key}"]`).value=value;form.querySelector('.chat-source-note').textContent='示例原文：比赛日期 11月7日，补充说明改为 11月8日；地点待定。请确认日期并补充地点。';});
document.addEventListener('change',e=>{if(e.target.matches('.chat-ai-source input[type="file"]'))e.target.closest('.chat-ai-source').querySelector('.chat-source-note').textContent='已选择：'+(e.target.files[0]?.name||'无文件')+'。仅展示文件名，识别请加载示例。'});
// Pointer capture 支持鼠标/触屏；只有拖动标题栏才移动窗口，表单和消息滚动保持独立。
const launcher=document.getElementById('chat-launcher'),dragHandle=chatPanel.querySelector('.chat-heading');
dragHandle.title='拖动标题栏移动窗口';dragHandle.tabIndex=0;dragHandle.setAttribute('aria-label','拖动聊天窗口，也可用方向键移动');
function placeWithinViewport(el,left,top,width,height){const gap=8;el.style.left=Math.max(gap,Math.min(left,innerWidth-width-gap))+'px';el.style.top=Math.max(gap,Math.min(top,innerHeight-height-gap))+'px';el.style.right='auto';el.style.bottom='auto';el.style.margin='0'}
function makeDraggable(el,handle){let drag=null,suppressClick=false;handle.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button')&&handle!==el||el.classList.contains('expanded'))return;const r=el.getBoundingClientRect();drag={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top,width:r.width,height:r.height,moved:false};handle.setPointerCapture(e.pointerId)});handle.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)<5)return;if(!drag.moved){drag.moved=true;el.style.width=drag.width+'px';if(el===chatPanel)el.style.height=drag.height+'px';el.classList.add('dragging')}placeWithinViewport(el,drag.left+dx,drag.top+dy,drag.width,drag.height)});const end=e=>{if(!drag||e.pointerId!==drag.id)return;suppressClick=drag.moved;drag=null;el.classList.remove('dragging');if(handle.hasPointerCapture(e.pointerId))handle.releasePointerCapture(e.pointerId);setTimeout(()=>suppressClick=false,0)};handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);handle.addEventListener('click',e=>{if(suppressClick){e.preventDefault();e.stopImmediatePropagation()}},true)}
makeDraggable(launcher,launcher);makeDraggable(chatPanel,dragHandle);
let compactPlacement='';document.getElementById('chat-expand').addEventListener('click',()=>{if(chatPanel.classList.contains('expanded')){compactPlacement=chatPanel.style.cssText;chatPanel.style.cssText=''}else{chatPanel.style.cssText=compactPlacement;clampFloatingElements()}});
function clampFloatingElements(){for(const el of [launcher,chatPanel]){if(el.hidden||el.classList.contains('expanded')||!el.style.left)continue;const r=el.getBoundingClientRect(),width=Math.min(r.width,innerWidth-16),height=Math.min(r.height,innerHeight-16);el.style.width=width+'px';if(el===chatPanel)el.style.height=height+'px';placeWithinViewport(el,r.left,r.top,width,height)}}
window.addEventListener('resize',clampFloatingElements);launcher.addEventListener('click',clampFloatingElements);
dragHandle.addEventListener('keydown',e=>{if(e.target!==dragHandle||chatPanel.classList.contains('expanded')||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const r=chatPanel.getBoundingClientRect();chatPanel.style.width=r.width+'px';chatPanel.style.height=r.height+'px';placeWithinViewport(chatPanel,r.left+(e.key==='ArrowLeft'?-20:e.key==='ArrowRight'?20:0),r.top+(e.key==='ArrowUp'?-20:e.key==='ArrowDown'?20:0),r.width,r.height)});
new MutationObserver(refreshChatContext).observe(app,{childList:true,subtree:true});
dialog.querySelector('.close').addEventListener('click',()=>dialog.close());render();
})();






